new='''        // Write as we go: the month-end ledger no longer has to fit in memory.
        // One open handle for the whole file; reopening it per line is slow on network shares.
        using var writer = new StreamWriter(path, append: false);
        writer.WriteLine(Header);

        var count = 0;
        foreach (var invoice in invoices)
        {
            writer.WriteLine(Line(invoice));
            count++;
        }

'''
open(p,'w').write(s.replace(old,new))
EOF
